import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/booker-show-detail-qr-code-share.CmAF8sB4.js";var i=JSON.parse(`{"title":"Schedule a Show","description":"","frontmatter":{},"headers":[],"relativePath":"guide/schedule-a-show.md","filePath":"guide/schedule-a-show.md"}`),a={name:`guide/schedule-a-show.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="schedule-a-show" tabindex="-1">Schedule a Show <a class="header-anchor" href="#schedule-a-show" aria-label="Permalink to &quot;Schedule a Show&quot;">​</a></h1><p>A booker&#39;s guide to putting a show on the calendar and building its card — from an empty date to a card ready to run. Written for anyone holding the BOOKER role (admins can do all of this too).</p><p><strong>Before you start:</strong> you need at least one show type and one arena set up by your admin. If those are missing, see <a href="./admin-getting-started.html">Admin Getting Started</a>.</p><hr><h2 id="step-1-—-create-the-show" tabindex="-1">Step 1 — Create the show <a class="header-anchor" href="#step-1-—-create-the-show" aria-label="Permalink to &quot;Step 1 — Create the show&quot;">​</a></h2><p>Open <strong>Show List</strong> from the navigation. At the top of the page is a creation row — fill it in and click <strong>Create</strong>:</p><ul><li><strong>Name</strong> — anything memorable (&quot;Collision #14&quot;). A show with the same name <em>and</em> date already on the calendar is rejected.</li><li><strong>Show Type</strong> — the kind of event. Weekly TV builds momentum; premium live events (PLEs) are the big ones where titles change and tournaments pay off.</li><li><strong>Season</strong> — optional. Shows grouped into a season feed season summaries and awards.</li><li><strong>Template</strong> — optional. A template pre-plans the card for you and can carry a gender division. Shows with a PLE template render highlighted in the list.</li><li><strong>League</strong> — optional. Assign the show to a league to have its matches count toward league standings.</li><li><strong>Universe</strong> — optional. Keeps the show inside one universe&#39;s continuity when you run several.</li><li><strong>Arena</strong> — where. Capacity feeds attendance and fan calculations.</li><li><strong>Show Date</strong> — when it runs on the calendar. Leave empty to schedule later.</li></ul><p>The show appears in the grid immediately as <strong>Scheduled</strong>. Click its name to open the detail view.</p><p><img src="/screenshots/booker-show-planning.png" alt="Show planning"></p><hr><h2 id="step-2-—-build-the-card" tabindex="-1">Step 2 — Build the card <a class="header-anchor" href="#step-2-—-build-the-card" aria-label="Permalink to &quot;Step 2 — Build the card&quot;">​</a></h2><p>A show is an ordered list of <strong>segments</strong>. On the show&#39;s detail page, use <strong>Add Segment</strong> for each one:</p><ol><li><strong>Pick a segment type</strong> — a match (singles, tag, triple threat — the list grows with your enabled expansions) or a non-wrestling segment like a promo.</li><li><strong>Set the participants</strong> — pick the wrestlers or teams. Filters help you find them fast: <strong>Alignment Filter</strong> (face/heel) and <strong>Gender Filter</strong> (pre-filled from the show template&#39;s gender division). <strong>Allow intergender participants</strong> follows your game settings when you want mixed matches.</li><li><strong>Add rules (optional)</strong> — stipulations like TLC or No DQ. The dialog warns you when a hot rivalry deserves a stipulation and none is set.</li><li><strong>Attach a championship (optional)</strong> — putting a title on the line means the winner leaves with (or keeps) the belt, and champions who retain gain fans.</li><li><strong>Referee (optional)</strong> — assign an NPC referee for flavor.</li></ol><p>New segments land as <strong>Pending</strong>. Reorder them with <strong>Save Order</strong> — the card runs top to bottom.</p><p>While you build, watch for the card-validation helpers: a wrestler booked twice, a stipulation that doesn&#39;t fit the participants, or a card without a proper main event are all flagged before showtime.</p><p><img src="/screenshots/booker-show-planning-proposed-card.png" alt="Proposed card"></p><hr><h2 id="step-3-—-designate-the-main-event" tabindex="-1">Step 3 — Designate the main event <a class="header-anchor" href="#step-3-—-designate-the-main-event" aria-label="Permalink to &quot;Step 3 — Designate the main event&quot;">​</a></h2><p>The last non-promo segment on the card is the night&#39;s headline. Main-event winners earn <strong>elevated fan gains</strong>, and the AI narration treats the segment as the climax — so put your hottest rivalry there.</p><hr><h2 id="step-4-—-run-the-show" tabindex="-1">Step 4 — Run the show <a class="header-anchor" href="#step-4-—-run-the-show" aria-label="Permalink to &quot;Step 4 — Run the show&quot;">​</a></h2><p>When the card is final, click <strong>Adjudicate Fans</strong> on the show detail page. The game adjudicates each pending segment in order:</p><ul><li>Match outcomes roll from wrestler stats, health, stamina, and momentum — the better-prepared wrestler usually wins, but upsets happen.</li><li>If you left winners unassigned, the rolls decide; you can also pre-set winners when adding a segment.</li><li>With an AI provider configured, every segment gets live narration and commentary you can share (shows expose a QR code link for viewers).</li><li>Fans, rankings, injuries, and notifications update as segments complete.</li></ul><p><img src="/screenshots/booker-show-detail-qr-code-share.png" alt="Show QR share"></p><hr><h2 id="step-5-—-after-the-bell" tabindex="-1">Step 5 — After the bell <a class="header-anchor" href="#step-5-—-after-the-bell" aria-label="Permalink to &quot;Step 5 — After the bell&quot;">​</a></h2><p>Once the show is final:</p><ul><li><strong>Results are visible</strong> to players and viewers on the show card.</li><li><strong>Fan reactions</strong> land on winners and losers; a decisive win over a popular opponent moves the needle most.</li><li><strong>Rivalries heat up or cool down</strong> based on who fought whom and how.</li><li><strong>Notifications</strong> tell wrestlers and title holders what changed.</li></ul><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./manage-rivalries.html">Manage Rivalries</a> — the heat system the Add Segment suggestions come from.</li><li><a href="./report-match-results.html">Report Match Results</a> — when your league assigns matches to players.</li><li><a href="./configure-tournaments.html">Configure Tournaments</a> — brackets that pay off on a show like this one.</li><li><a href="./run-a-season.html">Run a Season</a> — the yearly frame around the weekly grind.</li><li>The auto-generated <a href="./booker.html">Booker Overview</a> documents every booker screen.</li></ul>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};